INSERT INTO jokes (text, category, author, published_at, absurdity_level, adult, likes, dislikes) VALUES
('Мой код работает по принципу квантовой механики: пока заказчик не посмотрел, всё одновременно и готово, и сломано.', 'IT', 'Редакция Смехдера', '2025-07-01', 8, FALSE, 47, 3),
('— Почему ты не исправил баг? — Я исправил. Теперь это два бага, и они следят друг за другом.', 'IT', 'Редакция Смехдера', '2025-07-04', 7, FALSE, 39, 4),
('Разработчик зашёл в бар, заказал 1 пиво, 0 пива, -1 пиво, null пива. Бар выдержал. Потом зашёл пользователь и спросил, где туалет.', 'IT', 'Редакция Смехдера', '2025-07-08', 9, FALSE, 68, 6),
('Пароль должен содержать заглавную букву, цифру, символ, сюжетную арку и убедительную мотивацию главного героя.', 'IT', 'Редакция Смехдера', '2025-07-12', 7, FALSE, 54, 2),
('Нейросеть попросили заменить программиста. Она три часа настраивала окружение и сказала, что у неё всё работает.', 'IT', 'Редакция Смехдера', '2025-07-16', 8, FALSE, 63, 5),
('Удалил из проекта весь технический долг. Теперь это папка с одним файлом README: «Начать заново».', 'IT', 'Редакция Смехдера', '2025-07-20', 6, FALSE, 42, 3),
('Созвон назначили, чтобы понять, нужен ли созвон. Нужен. Завтра обсудим повестку.', 'Работа', 'Редакция Смехдера', '2025-07-24', 5, FALSE, 58, 4),
('Начальник сказал мыслить вне коробки. Я ушёл из офиса. Оказывается, коробкой он называл не офис.', 'Работа', 'Редакция Смехдера', '2025-07-29', 6, FALSE, 33, 5),
('Я не опоздал на работу. Я пришёл ровно тогда, когда моя мотивация смогла загрузиться.', 'Работа', 'Редакция Смехдера', '2025-08-02', 4, FALSE, 45, 6),
('В резюме написал «умею работать под давлением». Теперь сижу под кондиционером, а дедлайн давит сверху.', 'Работа', 'Редакция Смехдера', '2025-08-06', 6, FALSE, 51, 3),
('Корпоративный психолог посоветовал установить личные границы. Поставил турникет у рабочего стола.', 'Работа', 'Редакция Смехдера', '2025-08-10', 7, FALSE, 36, 4),
('Пятничная продуктивность — это когда пять минут работаешь и сорок пять минут закрываешь вкладки, чтобы уйти с чистой совестью.', 'Работа', 'Редакция Смехдера', '2025-08-15', 4, FALSE, 60, 7),
('Кот смотрел, как я работаю из дома, и наконец понял: человек тоже может весь день сидеть у окна и ничего не ловить.', 'Коты', 'Редакция Смехдера', '2025-08-19', 5, FALSE, 73, 2),
('Купил коту дорогой домик. Коробка довольна покупкой, кот тоже.', 'Коты', 'Редакция Смехдера', '2025-08-23', 3, FALSE, 82, 1),
('Кот разбудил меня в пять утра, чтобы сообщить срочную новость: миска наполовину пуста и правительство бездействует.', 'Коты', 'Редакция Смехдера', '2025-08-27', 7, FALSE, 77, 3),
('У кота девять жизней. Судя по тому, как он бежит на звук холодильника, все девять он планирует прожить одновременно.', 'Коты', 'Редакция Смехдера', '2025-09-01', 6, FALSE, 69, 2),
('Робот-пылесос застрял на носке и прислал уведомление: «Хозяин, мы оба знаем, кто здесь настоящий мусор».', 'Быт', 'Редакция Смехдера', '2025-09-05', 8, FALSE, 64, 4),
('Решил начать новую жизнь с понедельника. В понедельник выяснилось, что новая жизнь обновляется по вторникам.', 'Быт', 'Редакция Смехдера', '2025-09-09', 5, FALSE, 57, 6),
('Будильник — это устройство, которое каждый день спрашивает: «Ты точно хочешь сохранить текущий уровень сложности?»', 'Быт', 'Редакция Смехдера', '2025-09-13', 6, FALSE, 70, 3),
('Составил список дел на день. Первым пунктом было «составить список дел». Наконец-то появилась зачёркнутая задача.', 'Быт', 'Редакция Смехдера', '2025-09-17', 4, FALSE, 48, 5),
('Сосед сверлит так уверенно, будто в конце стены его ждёт нефть и квартальная премия.', 'Быт', 'Редакция Смехдера', '2025-09-21', 5, FALSE, 66, 4),
('Холодильник ночью светится не для удобства. Это допрос: «Ну и что мы здесь ищем в третий раз?»', 'Еда', 'Редакция Смехдера', '2025-09-25', 6, FALSE, 74, 3),
('Заказал салат и картошку фри. Салат нужен, чтобы картошка понимала: у нас серьёзные намерения.', 'Еда', 'Редакция Смехдера', '2025-09-29', 4, FALSE, 43, 5),
('Пельмени — это маленькие конверты, в которых мясо присылает зиме официальную жалобу.', 'Еда', 'Редакция Смехдера', '2025-10-03', 9, FALSE, 55, 7),
('Кофе не решает проблем. Но у проблем после кофе появляется менеджер проекта.', 'Еда', 'Редакция Смехдера', '2025-10-07', 5, FALSE, 81, 2),
('Преподаватель сказал, что экзамен покажет мои знания. Экзамен показал знания человека, который сидел через два ряда.', 'Учёба', 'Редакция Смехдера', '2025-10-11', 5, FALSE, 46, 6),
('Курсовая была настолько самостоятельной, что ушла гулять без меня и вернулась с чужим списком литературы.', 'Учёба', 'Редакция Смехдера', '2025-10-15', 7, FALSE, 52, 4),
('На лекции я записал главное: дату следующей лекции. Теперь у меня есть сериал, но я не понимаю сюжет.', 'Учёба', 'Редакция Смехдера', '2025-10-19', 5, FALSE, 38, 5),
('Мы с девушкой решили дать друг другу больше пространства. Теперь я живу в кладовке, зато пространство моё.', 'Отношения', 'Редакция Смехдера', '2025-10-23', 6, FALSE, 44, 7),
('На первом свидании сказал, что люблю долгие прогулки. Уже полчаса ищем, где я припарковался.', 'Отношения', 'Редакция Смехдера', '2025-10-27', 4, FALSE, 61, 3),
('Семейный бюджет — это когда двое пытаются вспомнить, кто из них заказал четыре одинаковых кабеля.', 'Отношения', 'Редакция Смехдера', '2025-11-01', 5, FALSE, 49, 4),
('Врач посоветовал больше двигаться. Теперь я каждые десять минут перекладываю телефон с одной стороны дивана на другую.', 'Здоровье', 'Редакция Смехдера', '2025-11-05', 5, FALSE, 53, 6),
('Купил фитнес-браслет. Теперь у меня есть профессиональный свидетель того, что я никуда не ходил.', 'Здоровье', 'Редакция Смехдера', '2025-11-09', 4, FALSE, 65, 3),
('Йог сказал отпустить всё, что меня тяготит. Я отпустил гантелю. Теперь тяготит ещё и счёт за пол.', 'Здоровье', 'Редакция Смехдера', '2025-11-13', 7, FALSE, 41, 5),
('В лифт зашёл пингвин и нажал девятый этаж. Никто не удивился: понедельник уже задал правила.', 'Абсурд', 'Редакция Смехдера', '2025-11-17', 10, FALSE, 59, 8),
('Купил глобус и сразу стал меньше переживать: все мои проблемы теперь размером с крошки.', 'Абсурд', 'Редакция Смехдера', '2025-11-21', 8, FALSE, 50, 4),
('Однажды стул решил стать столом. Получилось плохо, но совещание всё равно провели вокруг него.', 'Абсурд', 'Редакция Смехдера', '2025-11-25', 10, FALSE, 37, 9),
('Почтовый голубь принёс push-уведомление. Я смахнул его, теперь соседи жалуются.', 'Абсурд', 'Редакция Смехдера', '2025-11-29', 9, FALSE, 56, 5),
('Тень уволилась и ушла работать удалённо. Теперь по вечерам присылает силуэты в PDF.', 'Абсурд', 'Редакция Смехдера', '2025-12-03', 10, FALSE, 62, 6),
('Поставил чайник на тихий режим. Теперь он закипает и пишет: «Есть минутка созвониться?»', 'Абсурд', 'Редакция Смехдера', '2025-12-07', 9, FALSE, 71, 3);
